 await group('01 cached album is metadata only and adds verified local copy without play',async()=>{await fresh({control:true,seed:true});const n=report.rpc.length;await input().fill('MUSIC_FLOW Album');await openAlbum();await page.getByText('1 pistas · 1 discos').waitFor();assert.equal(report.rpc.length,n);const before=await page.evaluate(()=>MUSIC_FLOW.playCalls);await button('Añadir álbum').click();await page.getByText('Álbum listo en Biblioteca.').waitFor();assert.equal(await page.evaluate(()=>MUSIC_FLOW.playCalls),before);assert.equal(report.rpc.length,n);return {cached:true,telegram:0,play:0};});
